import{V as e,ht as t,nt as n,tt as r}from"./chunks/framework.wxcks8ca.js";var i=JSON.parse(`{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"kimi-code/faq.md","filePath":"zh/kimi-code/faq.md"}`),a={name:`kimi-code/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h1><h2 id="安装与鉴权" tabindex="-1">安装与鉴权 <a class="header-anchor" href="#安装与鉴权" aria-label="Permalink to “安装与鉴权”">​</a></h2><h3 id="login-时模型列表为空" tabindex="-1"><code>/login</code> 时模型列表为空 <a class="header-anchor" href="#login-时模型列表为空" aria-label="Permalink to “/login 时模型列表为空”">​</a></h3><p>如果在运行 <code>/login</code> 命令时看到 &quot;No models available for the selected platform&quot; 错误，可能是以下原因：</p><ul><li><strong>API 密钥无效或过期</strong>：检查你输入的 API 密钥是否正确，以及是否仍有效。</li><li><strong>网络连接问题</strong>：确认能正常访问 API 服务地址（如 <code>api.kimi.com</code> 或 <code>api.moonshot.cn</code>）。</li></ul><p><strong>注意区分平台</strong></p><p>Kimi Code 会员权益与 <a href="https://platform.kimi.com" target="_blank" rel="noreferrer">Kimi 开放平台</a> 有不同的 Base URL，配置时请注意 Base URL 与 API Key 的匹配是否正确。</p><table tabindex="0"><thead><tr><th>平台</th><th>Base URL</th><th>计费方式</th><th>Key 创建入口</th></tr></thead><tbody><tr><td><strong>Kimi Code</strong></td><td>Anthropic 兼容：<code>https://api.kimi.com/coding/</code></td><td>Kimi 会员订阅（含额度）</td><td><a href="https://www.kimi.com/code/console" target="_blank" rel="noreferrer">Kimi Code 控制台</a></td></tr><tr><td><strong>Kimi 开放平台</strong></td><td><code>https://api.moonshot.cn/v1</code></td><td>按量付费</td><td><a href="https://platform.kimi.com" target="_blank" rel="noreferrer">Kimi 开放平台官网</a></td></tr></tbody></table><h3 id="api-密钥无效" tabindex="-1">API 密钥无效 <a class="header-anchor" href="#api-密钥无效" aria-label="Permalink to “API 密钥无效”">​</a></h3><p>API 密钥无效可能的原因：</p><ul><li><strong>密钥输入错误</strong>：检查是否有多余的空格或遗漏的字符。</li><li><strong>密钥已过期或被撤销</strong>：在平台控制台确认密钥状态。</li></ul><h3 id="会员过期或配额用尽" tabindex="-1">会员过期或配额用尽 <a class="header-anchor" href="#会员过期或配额用尽" aria-label="Permalink to “会员过期或配额用尽”">​</a></h3><p>如果你使用 Kimi Code 平台，可以通过 <code>/usage</code> 命令查看当前的配额和会员状态。如果配额用尽或会员过期，需要在 <a href="https://kimi.com/code" target="_blank" rel="noreferrer">Kimi Code</a> 续费或升级。</p><h2 id="订阅相关" tabindex="-1">订阅相关 <a class="header-anchor" href="#订阅相关" aria-label="Permalink to “订阅相关”">​</a></h2><h3 id="如何开发票或升级会员" tabindex="-1">如何开发票或升级会员 <a class="header-anchor" href="#如何开发票或升级会员" aria-label="Permalink to “如何开发票或升级会员”">​</a></h3><p>请前往 <a href="https://www.kimi.com/membership/pricing?from=kfc_docs_faq#pricing-faq" target="_blank" rel="noreferrer">Kimi 会员权益页面</a>，根据页面指引完成开票申请或会员升级操作。</p><h2 id="交互问题" tabindex="-1">交互问题 <a class="header-anchor" href="#交互问题" aria-label="Permalink to “交互问题”">​</a></h2><h3 id="粘贴图片失败" tabindex="-1">粘贴图片失败 <a class="header-anchor" href="#粘贴图片失败" aria-label="Permalink to “粘贴图片失败”">​</a></h3><p>使用 <code>Ctrl-V</code> 粘贴图片时，如果提示 &quot;Current model does not support image input&quot;，说明当前模型不支持图片输入。</p><p>解决方法：</p><ul><li><strong>切换到支持图片的模型</strong>：使用支持 <code>image_in</code> 能力的模型。</li><li><strong>检查剪贴板内容</strong>：确保剪贴板中确实有图片数据，而非图片文件的路径。</li></ul><h2 id="更新与升级" tabindex="-1">更新与升级 <a class="header-anchor" href="#更新与升级" aria-label="Permalink to “更新与升级”">​</a></h2><h3 id="macos-首次运行缓慢" tabindex="-1">macOS 首次运行缓慢 <a class="header-anchor" href="#macos-首次运行缓慢" aria-label="Permalink to “macOS 首次运行缓慢”">​</a></h3><p>macOS 的 Gatekeeper 安全机制会在首次运行新程序时进行检查，导致启动变慢。解决方法：</p><ul><li><strong>等待检查完成</strong>：首次运行时耐心等待，后续启动会恢复正常。</li><li><strong>添加到开发者工具</strong>：在「系统设置 → 隐私与安全性 → 开发者工具」中添加你的终端应用。</li></ul><h3 id="如何升级-kimi-code-cli" tabindex="-1">如何升级 Kimi Code CLI <a class="header-anchor" href="#如何升级-kimi-code-cli" aria-label="Permalink to “如何升级 Kimi Code CLI”">​</a></h3><p>在 CLI 内运行 <code>kimi upgrade</code>，会自动检查最新版本并引导升级。也可以直接用包管理器：</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @moonshot-ai/kimi-code@latest</span></span></code></pre></div><h2 id="vs-code-扩展常见问题" tabindex="-1">VS Code 扩展常见问题 <a class="header-anchor" href="#vs-code-扩展常见问题" aria-label="Permalink to “VS Code 扩展常见问题”">​</a></h2><p>以下是 Kimi Code VS Code 扩展（VS Code Extension）的常见问题。</p><h3 id="vs-code-提示未打开工作区" tabindex="-1">VS Code 提示未打开工作区 <a class="header-anchor" href="#vs-code-提示未打开工作区" aria-label="Permalink to “VS Code 提示未打开工作区”">​</a></h3><p>请在 VS Code 中打开文件夹，Kimi Code VS Code 扩展需要工作区才能正常工作。</p><h3 id="vs-code-提示找不到-cli" tabindex="-1">VS Code 提示找不到 CLI <a class="header-anchor" href="#vs-code-提示找不到-cli" aria-label="Permalink to “VS Code 提示找不到 CLI”">​</a></h3><p>请手动安装 Kimi Code CLI 并在 VS Code 设置中配置 <code>kimi.executablePath</code>，或确保内置 CLI 存在。</p><h3 id="vs-code-登录失败" tabindex="-1">VS Code 登录失败 <a class="header-anchor" href="#vs-code-登录失败" aria-label="Permalink to “VS Code 登录失败”">​</a></h3><p>请尝试跳过登录使用 API 密钥模式，检查网络连接，或稍后通过 VS Code 扩展的操作菜单重试。</p><h3 id="vs-code-发送消息无响应" tabindex="-1">VS Code 发送消息无响应 <a class="header-anchor" href="#vs-code-发送消息无响应" aria-label="Permalink to “VS Code 发送消息无响应”">​</a></h3><p>请确认 Kimi Code CLI 可用、模型已配置且 VS Code 中已打开工作区文件夹。通过 &quot;Kimi Code: Show Logs&quot; 查看错误日志。</p><h3 id="vs-code-连接超时" tabindex="-1">VS Code 连接超时 <a class="header-anchor" href="#vs-code-连接超时" aria-label="Permalink to “VS Code 连接超时”">​</a></h3><p>若 30 秒内无响应将超时。请检查网络后重试。</p><h3 id="vs-code-发消息前报错" tabindex="-1">VS Code 发消息前报错 <a class="header-anchor" href="#vs-code-发消息前报错" aria-label="Permalink to “VS Code 发消息前报错”">​</a></h3><p>某些错误会阻止在 VS Code 中发送消息，如 Kimi Code CLI 未找到、版本过低、未登录或会话忙碌。错误将以 toast 提示，您的输入将被保留以便重试。</p><h2 id="反馈与联系" tabindex="-1">反馈与联系 <a class="header-anchor" href="#反馈与联系" aria-label="Permalink to “反馈与联系”">​</a></h2><h3 id="文档未能解决问题" tabindex="-1">文档未能解决问题 <a class="header-anchor" href="#文档未能解决问题" aria-label="Permalink to “文档未能解决问题”">​</a></h3><p>如果以上内容未能解决您的问题，欢迎通过邮件联系我们：<a href="mailto:code@moonshot.ai" target="_blank" rel="noreferrer">code@moonshot.ai</a>。请在邮件中描述您遇到的问题、操作步骤及相关日志信息，我们会尽快回复。</p>`,45)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};